export function FontWeight({
  weight = "{{weight}}",
  text = "{{text}}",
  size = {{size}},
  color = "{{color}}",
}) {
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 300 }}>
      <p style={{ margin: 0, fontWeight: Number(weight), fontSize: size, color }}>{text}</p>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>font-weight: {weight}</p>
    </div>
  );
}
